using UnityEngine;

namespace Astrea.BattleActions;

public class ChooseCorruptPurifyDieAction : ChooseDiceAction
{
	[Header("Action Specifics")]
	[SerializeField]
	protected bool interactWithCorruptAction;

	[SerializeField]
	private bool useOnEnemiesAndCompanions = true;

	[SerializeField]
	private bool ignoreCheckCondition;

	public bool UseOnEnemiesAndCompanions => useOnEnemiesAndCompanions;

	protected CurrentCorruptedAnimals currentCorruptedAnimals => ReferenceSingleton<AssetsReference>.Instance.CurrentCorruptedAnimals;

	protected CurrentCompanions currentCompanions => ReferenceSingleton<AssetsReference>.Instance.CurrentCompanions;

	public override bool CheckConditionToBeCasted(bool playerHand, DiceOwnerEnum diceOwnerEnum)
	{
		if (ignoreCheckCondition)
		{
			return true;
		}
		if (!useOnEnemiesAndCompanions)
		{
			return ReferenceSingleton<PlayerDiceHandHolder>.Instance.IsAnyPurifyCorruptAction(interactWithCorruptAction);
		}
		for (int i = 0; i < currentCorruptedAnimals.activeCorruptedAnimals.Count; i++)
		{
			CorruptedAnimalActivation component = currentCorruptedAnimals.activeCorruptedAnimals[i].GetComponent<CorruptedAnimalActivation>();
			if (!component.BasicDiceSpawned)
			{
				continue;
			}
			DiceInstance basicDiceInstance = component.BasicDiceInstance;
			if (CheckInteraction(basicDiceInstance))
			{
				return true;
			}
			if (component.IsBoosted && component.BoostDiceSpawned)
			{
				DiceInstance boostDiceInstance = component.BoostDiceInstance;
				if (CheckInteraction(boostDiceInstance))
				{
					return true;
				}
			}
		}
		for (int j = 0; j < currentCompanions.ActiveCompanions.Count; j++)
		{
			CompanionAbility component2 = currentCompanions.ActiveCompanions[j].GetComponent<CompanionAbility>();
			if (!component2.BasicDiceSpawned)
			{
				continue;
			}
			DiceInstance basicDiceInstance2 = component2.BasicDiceInstance;
			if (basicDiceInstance2.ActionEnabled && CheckInteraction(basicDiceInstance2))
			{
				return true;
			}
			if (component2.IsBoosted && component2.BoostDiceSpawned)
			{
				DiceInstance boostDiceInstance2 = component2.BoostDiceInstance;
				if (boostDiceInstance2.ActionEnabled && CheckInteraction(boostDiceInstance2))
				{
					return true;
				}
			}
		}
		return ReferenceSingleton<PlayerDiceHandHolder>.Instance.IsAnyPurifyCorruptAction(interactWithCorruptAction);
	}

	protected bool CheckInteraction(DiceInstance diceInstance)
	{
		if (interactWithCorruptAction)
		{
			if (diceInstance.ActionFace.BattleAction is CorruptAction)
			{
				return true;
			}
			if (diceInstance.ActionFace.EnableSecondAction && diceInstance.ActionFace.SecondBattleAction is CorruptAction)
			{
				return true;
			}
		}
		else
		{
			if (diceInstance.ActionFace.BattleAction is PurifyAction)
			{
				return true;
			}
			if (diceInstance.ActionFace.EnableSecondAction && diceInstance.ActionFace.SecondBattleAction is PurifyAction)
			{
				return true;
			}
		}
		return false;
	}

	public override bool CheckCondition(DiceInstance diceInstance)
	{
		return CheckInteraction(diceInstance);
	}
}
